using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Initialize A and B with the same semantics as the original C init_array().
 *
 * C version:
 *
 *   *alpha = 1.5;
 *   for (i = 0; i < m; i++) {
 *     for (j = 0; j < i; j++) {
 *       A[i][j] = (DATA_TYPE)((i+j) % m)/m;
 *     }
 *     A[i][i] = 1.0;
 *     for (j = 0; j < n; j++) {
 *       B[i][j] = (DATA_TYPE)((n+(i-j)) % n)/n;
 *     }
 *   }
 *
 * Mapping to Halide Buffers:
 *   - A is declared in C as A[m][m] and accessed as A[i][j].
 *     We store it as Buffer A(width=m, height=m) and access as A(j, i).
 *   - B is declared in C as B[m][n] and accessed as B[i][j].
 *     We store it as Buffer B(width=n, height=m) and access as B(j, i).
 */
static void init_array(int m, int n,
                       num_t *alpha,
                       Halide::Buffer<num_t, 2> A,
                       Halide::Buffer<num_t, 2> B) {
    *alpha = static_cast<num_t>(1.5);

    Var i("i"), j("j");
    Func init_A("init_A"), init_B("init_B");

    // Make Expr versions of m and n for use inside Halide expressions.
    Expr m_expr = m;
    Expr n_expr = n;

    // Constants in Halide Expr form, matching num_t.
    Expr one  = Expr(static_cast<num_t>(1.0));
    Expr zero = Expr(static_cast<num_t>(0.0));

    // A(i,j):
    //   For j < i:  ((i + j) % m) / m
    //   For j == i: 1.0
    //   For j > i:  0.0 (never used by the kernel, but we define it anyway)
    Expr a_lower = cast<num_t>(((i + j) % m_expr)) / cast<num_t>(m_expr);
    init_A(j, i) =
        select(j < i,
               a_lower,
               select(j == i, one, zero));

    // B(i,j): ((n + (i - j)) % n) / n
    Expr b_num = (n_expr + (i - j)) % n_expr;
    init_B(j, i) =
        cast<num_t>(b_num) / cast<num_t>(n_expr);

    // Basic CPU schedule for initialization: parallelize rows, vectorize columns.
    Target target = get_jit_target_from_environment();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    init_A.compute_root()
          .parallel(i)
          .vectorize(j, vec_width);

    init_B.compute_root()
          .parallel(i)
          .vectorize(j, vec_width);

    init_A.realize(A);
    init_B.realize(B);
}

int main(int argc, char *argv[]) {
    // Problem sizes (compile-time constants from PolyBench headers)
    int m = M;
    int n = N;

    // Scalars and arrays
    num_t alpha;
    // Buffer layout: width = number of columns, height = number of rows
    // A: M x M  -> Buffer(m, m) accessed as A(j, i) == A[i][j] in C
    // B: M x N  -> Buffer(n, m) accessed as B(j, i) == B[i][j] in C
    Buffer<num_t, 2> A(m, m);
    Buffer<num_t, 2> B(n, m);

    // Initialize data
    init_array(m, n, &alpha, A, B);

    // Halide ImageParams corresponding to A and B (read-only views)
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");
    A_param.set(A);
    B_param.set(B);

    // Vars
    Var i("i"), j("j");

    // We will use the host target to choose a good vector width.
    Target target = get_jit_target_from_environment();
    const int vec_width = target.natural_vector_size(type_of<num_t>());
    // Tile size for the j (column) dimension: tuneable constant.
    const int j_tile = std::max(16, 16 * vec_width);

    // Func representing the result B := alpha * A^T * B
    //
    // Original kernel:
    //
    // for (i = 0; i < M; i++)
    //   for (j = 0; j < N; j++) {
    //     for (k = i+1; k < M; k++)
    //       B[i][j] += A[k][i] * B[k][j];
    //     B[i][j] = alpha * B[i][j];
    //   }
    //
    // Dependency analysis shows that all reads of B[k][j] use the *original* B
    // (no in-place dependence across rows), so we can write:
    //
    //   B_out[i][j] = alpha * ( B_in[i][j] +
    //                           sum_{k = i+1..M-1} A[k][i] * B_in[k][j] )
    //
    // Mapping indices to Halide:
    //   A[k][i]  -> A_param(i, k)
    //   B[k][j]  -> B_param(j, k)
    //   B[i][j]  -> B_param(j, i)
    //
    // Instead of a select inside the reduction, we express the k-range
    // exactly via a k-domain that depends on i: k in [i+1, M-1].
    Func trmm("trmm");

    Expr alpha_expr = Expr(alpha);
    Expr m_expr = m;

    // Pure definition: initial contribution alpha * B(i,j).
    trmm(j, i) = alpha_expr * B_param(j, i);

    // Reduction over k = i+1 .. M-1
    RDom k_dom(i + 1, m_expr - (i + 1), "k");
    RVar k = k_dom.x;

    // Accumulate alpha * A[i][k] * B[k][j] into trmm(i,j).
    trmm(j, i) += alpha_expr * A_param(i, k) * B_param(j, k);

    // ------------------------------------------------------------------
    // Scheduling
    // ------------------------------------------------------------------
    //
    // Goal:
    //   - Parallelize across rows i (outer dimension).
    //   - Tile and vectorize across columns j (inner dimension), so that
    //     B_param(j, k) accesses are contiguous and vectorizable.
    //   - For the reduction stage, use loop order i -> k -> j so that
    //     for each (i,k) we stream across j in a tight inner loop.

    Var jo("jo"), ji("ji");

    // Compute the whole output at root.
    trmm.compute_root();

    // Pure stage (initial alpha * B term):
    //  for i (parallel)
    //    for jo
    //      for ji (vectorized)
    trmm
        .split(j, jo, ji, j_tile)
        .reorder(ji, jo, i)      // ji innermost, then tile index jo, then row i
        .vectorize(ji, vec_width)
        .parallel(i);

    // Reduction stage:
    //  for i (parallel)
    //    for k
    //      for jo
    //        for ji (vectorized)
    trmm.update()
        .split(j, jo, ji, j_tile)
        .reorder(ji, k, jo, i)   // ji innermost, then k, then tile jo, then row i
        .vectorize(ji, vec_width)
        .parallel(i);

    // Compile the kernel to machine code for the chosen target.
    trmm.compile_jit(target);

    // Output buffer for the result (same logical layout as B)
    Buffer<num_t, 2> B_result(n, m);

    // Time the execution
    auto start = std::chrono::high_resolution_clock::now();

    trmm.realize(B_result);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result to avoid dead-code elimination
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < m; ii++) {
            for (int jj = 0; jj < n; jj++) {
                // Remember: B_result(jj, ii) == B[ii][jj] in the original C code
                std::cerr << B_result(jj, ii) << '\n';
            }
        }
    }

    // Print elapsed time in seconds
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
