    //   for (j = 0; j < N; j++) {
    //     for (k = i+1; k < M; k++)
    //       B[i][j] += A[k][i] * B[k][j];
    //     B[i][j] = alpha * B[i][j];
    //   }
    //
    // Careful dependency analysis shows that all reads of B[k][j] use the
    // *original* B (no in-place dependence across rows), so we can express
    // the final value in closed form as:
    //
    //   B_out[i][j] = alpha * ( B_in[i][j] +
    //                           sum_{k = i+1..M-1} A[k][i] * B_in[k][j] )
    //
    // Mapping indices to Halide:
    //   A[k][i]  -> A_param(i, k)
    //   B[k][j]  -> B_param(j, k)
    //   B[i][j]  -> B_param(j, i)
    //
    // We implement "k from i+1..M-1" via a select inside a reduction over k in [0..M-1].
    Func trmm("trmm");

    Expr alpha_expr = Expr(alpha);
    Expr zero = cast<num_t>(Expr(0));

    trmm(j, i) = alpha_expr *
                 (B_param(j, i) +
                  sum(select(k > i,
                             A_param(i, k) * B_param(j, k),
                             zero)));

    // ----------------- TRMM schedule (performance-critical) -----------------
    //
    // 2D domain: i in [0, m), j in [0, n)
    // Memory layout: B_param(j, i) is row-major in j.
    // Strategy:
    //   - make j the innermost loop for unit-stride access
    //   - vectorize across j
    //   - parallelize across i (rows), which are independent
