    trmm
        .reorder(j, i)        // j innermost for contiguous access
        .vectorize(j, vec_width)
        .parallel(i);         // distribute rows across cores

    // Update (reduction) step over k:
    // Default loop structure after this schedule is roughly:
    //
    // for (k = 0; k < m; k++)
    //   for (i in parallel)
    //     for (j vectorized)
    //        trmm(j,i) += select(k > i, A(i,k) * B(j,k), 0);
    //
    // which reuses A(:,k) and B(:,k) well and streams along j.
    trmm.update()
        .reorder(j, i, k)     // k outer, i middle, j inner
        .vectorize(j, vec_width)
        .parallel(i);
    // -----------------------------------------------------------------------

    // Compile the kernel to machine code
    trmm.compile_jit();

    // Output buffer for the result (same logical layout as B)
    Buffer<num_t, 2> B_result(n, m);

